using Challenge;void C(string id,Func<bool> f){try{Console.WriteLine($"{id}|{(f()?"pass":"fail")}");}catch{Console.WriteLine($"{id}|fail");}}C("C01",()=>{var d=new InboxStore();var s=new Consumer(d);s.Handle("1");s.Handle("1");return d.Invoices.Count==1;});C("C02",()=>{var d=new InboxStore();new Consumer(d).Handle("1");new Consumer(d).Handle("1");return d.Invoices.Count==1;});C("C03",()=>{var d=new InboxStore();try{new Consumer(d).Handle("1",true);}catch{}new Consumer(d).Handle("1");return d.Invoices.Count==1&&d.Processed.Contains("1");});C("C04",()=>{var d=new InboxStore();var s=new Consumer(d);s.Handle("1");s.Handle("2");return d.Invoices.Count==2;});C("C05",()=>{var d=new InboxStore();var s=new Consumer(d);return s.Handle("1")&&s.Handle("1");});
